<template>
  <div class="trade-container">
    <div class="trade-backdrop" :inert="detail?'':null" :aria-hidden="detail?'true':null" @mousedown.stop @keydown.esc.stop.prevent="close" @keydown.tab="trapFocus">
      <section ref="panel" class="trade-panel" role="dialog" aria-modal="true" aria-labelledby="trade-title" :aria-busy="busy || state.phase==='committing'">
        <header><div><small>ÉCHANGE ENTRE AMIS · AVENTURE</small><h2 id="trade-title">{{ title }}</h2></div><button ref="close" data-gamepad-back aria-label="Fermer l’échange" :disabled="locked || busy" @click="close">×</button></header>
        <p v-if="!connected" class="trade-notice" role="status">Connexion interrompue. Reconnexion et vérification de l’échange…</p>
        <p v-if="error || inventoryError" class="trade-error" role="alert">{{ error || inventoryError }}</p>
        <div class="trade-body">
          <template v-if="state.phase==='invited'"><div class="trade-waiting"><journal-icon name="friends"/><h3>Invitation envoyée à {{ peerName }}</h3><p>Ton ami doit l’accepter dans son menu Amis.</p><p>Rien n’est transféré pendant cette attente.</p></div></template>
          <template v-else-if="state.phase==='cancelled'"><div class="trade-waiting"><h3>Échange terminé</h3><p>{{ state.reason }}</p></div></template>
          <template v-else>
            <p class="trade-step" role="status">{{ stepText }}</p>
            <div class="trade-offers"><trade-offer :offer="ownOffer" :label="completed?'Tu as donné':'Ton offre'" side="own" :editable="state.phase==='open'" :busy="busy || !connected" @details="showDetails" @pokemon="changePokemon" @quantity="changeQuantity" @remove="removeItem"/><trade-offer :offer="peerOffer" :label="completed?'Tu as reçu':`Offre de ${peerName}`" side="peer" @details="showDetails"/></div>
            <div v-if="state.phase==='open'" class="trade-editor">
              <div class="trade-editor-heading"><h3>Composer ton offre</h3><button data-trade-refresh-inventory :disabled="busy || loadingInventory" @click="loadInventory">Actualiser</button></div>
              <p class="trade-help">Un Pokémon et jusqu’à six objets différents. Tu peux aussi faire un don. Une modification retire les deux validations.</p>
              <nav class="trade-tabs" aria-label="Contenu de mon offre"><button :aria-pressed="tab==='pokemon'" data-trade-tab="pokemon" @click="tab='pokemon'">Pokémon</button><button :aria-pressed="tab==='items'" data-trade-tab="items" @click="tab='items'">Objets</button></nav>
              <p v-if="loadingInventory" class="trade-help" role="status">Chargement de ton équipe, du PC et du sac…</p>
              <template v-else-if="inventory">
                <div v-if="tab==='pokemon'" class="trade-pokemon-choices">
                  <label>Emplacement<select v-model="box" data-trade-box :disabled="busy"><option value="team">Équipe</option><option v-for="n in inventory.boxCount" :key="n" :value="String(n-1)">Boîte {{ n }} · {{ inventory.entries.filter(e=>e.box===n-1).length }} Pokémon</option></select></label>
                  <label>Chercher un Pokémon<input v-model="query" type="search" placeholder="Nom…" :disabled="busy"/></label>
                  <div class="trade-choice-list"><button v-for="p in candidatePokemon" :key="p.uuid" :data-trade-pokemon="p.uuid" :aria-pressed="ownOffer?.pokemon?.uuid===p.uuid" :disabled="busy || !connected || !!p.unavailableReason" @click="changePokemon(p.uuid)"><pokemon-portrait :src="`${$assetBase}img/pokemon/front/${p.pokemonId}.png`"/><span><strong>{{ p.nickname || p.name }}</strong><small>Niv. {{ p.level }} · {{ p.currentHp }}/{{ p.maxHp }} PV</small><small v-if="p.unavailableReason">{{ p.unavailableReason }}</small></span><potential-star :value="p.potential"/></button><p v-if="!candidatePokemon.length" class="trade-help">Aucun Pokémon à cet emplacement pour cette recherche.</p></div>
                </div>
                <div v-else class="trade-item-choices">
                  <label>Chercher un objet<input v-model="itemQuery" type="search" placeholder="Nom ou effet…" :disabled="busy"/></label><label>Poche<select v-model="itemPocket" :disabled="busy"><option value="all">Toutes</option><option v-for="p in pockets" :key="p.key" :value="p.key">{{ p.name }}</option></select></label>
                  <p class="trade-help">Les objets clés, la canne et le Multi Exp restent personnels.</p>
                  <div class="trade-choice-list"><button v-for="item in candidateItems" :key="item.key" :data-trade-item="item.key" :aria-pressed="selectedItem===item.key" :disabled="busy || ownItems.length>=6" @click="selectedItem=item.key;quantity=1"><bag-item-icon :pocket="pocket(item)" :item-key="item.key"/><span><strong>{{ item.name }}</strong><small>{{ item.description }}</small></span><small>×{{ item.quantity }}</small></button><p v-if="!candidateItems.length" class="trade-help">Aucun objet disponible pour cette recherche.</p></div>
                  <div v-if="selectedItemRecord" class="trade-add-item"><label>Quantité<input v-model.number="quantity" data-trade-item-quantity type="number" min="1" :max="Math.min(99,selectedItemRecord.quantity)" :disabled="busy"/></label><button data-trade-add-item :disabled="busy || !connected || !validQuantity || ownItems.length>=6" @click="addItem">Ajouter à l’offre</button></div>
                </div>
              </template>
            </div>
            <p v-if="state.error && state.phase==='open'" class="trade-validation" role="status">{{ state.error }}</p>
            <div v-if="['open','review'].includes(state.phase)" class="trade-validations"><span :class="{validated:state.ready[ownIndex]}">{{ state.ready[ownIndex]?'✓ Offre validée':'○ Ton offre à valider' }}</span><span :class="{validated:state.ready[1-ownIndex]}">{{ state.ready[1-ownIndex]?`✓ ${peerName} a validé`:`○ En attente de ${peerName}` }}</span></div>
            <p v-if="state.phase==='recovering'" class="trade-validation" role="status">{{ state.reason }} Les possessions restent protégées pendant la vérification.</p>
          </template>
        </div>
        <footer>
          <button v-if="!completed && state.phase!=='cancelled'" class="trade-secondary" data-trade-cancel :disabled="busy || locked || !connected" @click="$emit('cancel')">Annuler</button>
          <button v-if="state.phase==='open'" class="trade-primary" data-trade-ready :disabled="busy || !connected || !!state.error || state.ready[ownIndex] || loadingInventory" @click="$emit('action','ready')">{{ state.ready[ownIndex]?'Offre validée':'Valider mon offre' }}</button>
          <template v-else-if="state.phase==='review'"><button class="trade-secondary" data-trade-edit :disabled="busy || !connected" @click="$emit('action','edit')">Modifier</button><button class="trade-primary" data-trade-confirm :disabled="busy || !connected || state.confirmed[ownIndex]" @click="$emit('action','confirm')">{{ state.confirmed[ownIndex]?'Confirmation envoyée':'Confirmer l’échange' }}</button></template>
          <button v-else-if="state.phase==='committing'" class="trade-primary" disabled>Transfert et sauvegarde…</button>
          <button v-else-if="state.phase==='recovering'" class="trade-primary" :disabled="busy || !connected" @click="$emit('action','refresh')">Vérifier la sauvegarde</button>
          <button v-else-if="completed || state.phase==='cancelled'" class="trade-primary" data-trade-close :disabled="busy || !connected" @click="$emit('action','close')">Continuer</button>
        </footer>
      </section>
    </div>
    <pokemon-details v-if="detail" class="trade-pokemon-details" :pokemon="detail" :position="1" :total="1" :read-only="true" context-label="ÉCHANGE ENTRE AMIS" footer-label="Caractéristiques du Pokémon proposé" @close="detail=null"/>
  </div>
</template>
<script>
import TradeOffer from './TradeOffer.vue';
import PokemonPortrait from '../PokemonPortrait.vue';
import PotentialStar from '../PotentialStar.vue';
import PokemonDetails from '../menu/PokemonDetails.vue';
import JournalIcon from '../menu/JournalIcon.vue';
import BagItemIcon from '../menu/BagItemIcon.vue';
import {computerPokemonDetails} from '@/services/pokemonComputer';
import {BAG_POCKETS,bagPocket} from '@/services/bagPockets';
const fold=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export default {
  components:{TradeOffer,PokemonPortrait,PotentialStar,PokemonDetails,JournalIcon,BagItemIcon},props:{state:{type:Object,required:true},userId:Number,busy:Boolean,error:String,connected:Boolean,command:{type:Function,required:true}},
  data:()=>({inventory:null,loadingInventory:false,inventoryError:'',tab:'pokemon',box:'team',query:'',itemQuery:'',itemPocket:'all',selectedItem:null,quantity:1,detail:null,previousFocus:null}),
  computed:{
    ownIndex(){const i=this.state.participants.findIndex(p=>p.id===this.userId);return i<0?0:i;},peerName(){return this.state.participants[1-this.ownIndex]?.username || 'ton ami';},ownOffer(){return this.state.offers?.[this.ownIndex];},peerOffer(){return this.state.offers?.[1-this.ownIndex];},ownItems(){return this.ownOffer?.items||[];},completed(){return this.state.phase==='completed';},locked(){return ['committing','recovering'].includes(this.state.phase);},title(){return this.completed?'Échange terminé':this.state.phase==='review'?'Vérifier l’échange':'Échange avec '+this.peerName;},stepText(){return{open:'1 · Choisissez vos offres. Aucun transfert avant la confirmation finale.',review:'2 · Vérifiez les deux offres. Vos deux confirmations déclencheront le transfert.',committing:'Transfert en cours. Attends la confirmation de sauvegarde.',recovering:'Vérification du résultat sur le serveur…',completed:'Le transfert est sauvegardé. Vos équipes et vos sacs sont actualisés.'}[this.state.phase]||'';},
    candidatePokemon(){const list=this.box==='team'?this.inventory?.team||[]:(this.inventory?.entries||[]).filter(e=>e.box===Number(this.box)).map(e=>e.pokemon);return list.filter(p=>fold(p.name+' '+p.nickname).includes(fold(this.query)));},
    candidateItems(){return(this.inventory?.items||[]).filter(i=>!this.ownItems.some(o=>o.key===i.key)&&(this.itemPocket==='all'||bagPocket(i)===this.itemPocket)&&fold(i.name+' '+i.description).includes(fold(this.itemQuery)));},
    pockets(){return BAG_POCKETS.filter(p=>(this.inventory?.items||[]).some(i=>bagPocket(i)===p.key));},selectedItemRecord(){return this.candidateItems.find(i=>i.key===this.selectedItem);},validQuantity(){return Number.isInteger(this.quantity)&&this.quantity>0&&this.quantity<=Math.min(99,this.selectedItemRecord?.quantity||0);}
  },
  watch:{'state.phase'(phase,old){if(phase==='open'&&old==='invited')this.loadInventory();},'state.revision'(){if(this.ownItems.some(i=>i.key===this.selectedItem))this.selectedItem=null;}},
  mounted(){this.previousFocus=document.activeElement;this.$refs.close.focus({preventScroll:true});if(this.state.phase==='open')this.loadInventory();},beforeDestroy(){const p=this.previousFocus;this.$nextTick(()=>{(p?.isConnected?p:document.querySelector('.menu-toggle-btn'))?.focus({preventScroll:true});});},
  methods:{
    pocket:bagPocket,
    async loadInventory(){if(this.loadingInventory||this.state.phase!=='open')return;this.loadingInventory=true;this.inventoryError='';try{const r=await this.command('inventory',{id:this.state.id});this.inventory=r.inventory;}catch(e){this.inventoryError=e.message;}finally{this.loadingInventory=false;}},
    offer(pokemonUuid,items){this.$emit('action','offer',{pokemonUuid: pokemonUuid||null,items:items.map(({key,quantity})=>({key,quantity}))});},
    changePokemon(uuid){this.offer(uuid,this.ownItems);},removeItem(key){this.offer(this.ownOffer?.pokemon?.uuid,this.ownItems.filter(i=>i.key!==key));},changeQuantity({key,value}){this.offer(this.ownOffer?.pokemon?.uuid,this.ownItems.map(i=>i.key===key?{...i,quantity:value}:i));},addItem(){if(this.validQuantity)this.offer(this.ownOffer?.pokemon?.uuid,[...this.ownItems,{key:this.selectedItem,quantity:this.quantity}]);},
    showDetails(pokemon){this.detail=computerPokemonDetails(pokemon);},close(){if(this.detail){this.detail=null;return;}if(this.locked||this.busy)return;if(['completed','cancelled'].includes(this.state.phase))this.$emit('action','close');else this.$emit('cancel');},
    trapFocus(event){const nodes=[...this.$refs.panel.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  }
};
</script>
<style scoped>
