lor:var(--journal-accent)}.trade-pokemon-choices,.trade-item-choices{display:grid;grid-template-columns:1fr 1fr;gap:10px}.trade-pokemon-choices>label,.trade-item-choices>label,.trade-add-item>label{display:grid;gap:4px;font-size:11px;color:var(--journal-muted)}label input,label select{width:100%;min-width:0;font-size:13px}.trade-choice-list{grid-column:1/-1;display:flex;flex-direction:column;gap:7px;max-height:240px;overflow:auto;overscroll-behavior:contain;padding:3px}.trade-choice-list>button{display:flex;align-items:center;text-align:left;gap:10px;padding:9px 11px;flex:none}.trade-choice-list>button[aria-pressed=true]{border-color:var(--journal-accent);background:var(--journal-selected)}.trade-choice-list .pokemon-portrait{width:44px;flex:none}.trade-choice-list .bag-object-icon{width:28px;height:28px;flex:none}.trade-choice-list button>span{min-width:0;flex:1}.trade-choice-list strong{display:block;font-size:12px;overflow-wrap:anywhere}.trade-choice-list small{display:block;font-size:10px;color:var(--journal-muted)}.trade-item-choices>.trade-help{grid-column:1/-1;margin:0}.trade-add-item{grid-column:1/-1;display:flex;align-items:flex-end;gap:10px}.trade-add-item>label{width:92px}.trade-add-item>button{flex:1;background:var(--journal-selected)}.trade-validations{display:flex;gap:10px;justify-content:space-between;margin-top:14px;font-size:11px;color:var(--journal-muted)}.trade-validations .validated{color:var(--journal-accent);font-weight:600}.trade-validation{padding:10px 12px;background:var(--journal-soft);border-left:3px solid var(--journal-progress);font-size:11px;margin:14px 0 0}.trade-notice,.trade-error{padding:9px 18px;margin:0;font-size:12px;background:var(--journal-soft)}.trade-error{color:var(--journal-danger)}footer{display:flex;gap:8px;padding:12px 18px;border-top:1px solid var(--journal-border);background:var(--journal-card);flex:none}.trade-primary{margin-left:auto;background:var(--journal-accent);color:var(--journal-on-accent);font-weight:600}.trade-secondary{background:transparent}.trade-waiting{text-align:center;max-width:420px;margin:0 auto;padding:25px 12px;color:var(--journal-muted)}.trade-waiting>.journal-icon{width:44px;height:44px;margin:0 auto 12px;color:var(--journal-accent)}.trade-waiting h3{font:23px Georgia,serif;color:var(--journal-heading)}.trade-pokemon-details{z-index:3500!important}@media(max-width:600px){.trade-backdrop{padding:8px}.trade-panel{max-height:calc(100dvh - 16px);border-radius:14px}header{padding:12px 14px}h2{font-size:23px}.trade-body{padding:12px}.trade-offers{grid-template-columns:1fr;gap:8px}.trade-validations{flex-direction:column;gap:4px}footer{padding:10px;flex-wrap:wrap}.trade-primary{flex:1}.trade-choice-list{max-height:230px}}@media(max-height:480px){header{padding:8px 14px}h2{font-size:21px}.trade-body{padding:10px 14px}footer{padding:8px 14px}}
</style>
